/**
 * Reading of the TEXT of a message at the part level.
 *
 * It lives in shared because the main and the renderer need to answer the SAME
 * question with the same rule: which snippet of an assistant message is the
 * answer of the turn. The renderer uses it in the bubble and in the read-aloud; the
 * main, in the preview of the native notification — which before took the FIRST text
 * part and announced the preamble of the turn ("I will implement…") instead of the
 * answer.
 */
import type { ChatMessage, MessagePart, TextPart } from './chat'

/**
 * Text generated by the engine in INTERNAL continuations of the turn (anti-overclaim
 * check nudges and checklist closing nudges) — it is never the
 * answer to the user. 'nudge'/'todo' render dimmed; 'internal' does not even
 * get rendered. See NO_CHANGES_PROMPT/TODO_COMPLETION_PROMPT and the
 * source markers in chat-engine.ts.
 */
export function isEngineText(source: TextPart['source']): boolean {
  return source === 'nudge' || source === 'todo' || source === 'internal'
}

/**
 * Index (in segments) of the first part of the LAST contiguous text block
 * of the message. A block is a run of consecutive text/reasoning parts,
 * broken only by something that is not text (tool, agent, image): two
 * text parts separated only by reasoning are the SAME answer — it is what
 * happens in a cut by token limit followed by AUTO_CONTINUE, in
 * which the continuation reopens the reasoning and the text resumes where it was cut.
 * Without this the UI promoted the continuation to "final answer" and erased the previous
 * snippet (the "overlapping answer" by a short summary). Engine texts
 * are invisible to the run (they neither start nor break a block): besides never
 * stealing the place of the final answer, they do not erase the real block on the left
 * when they show up after it.
 */
export function lastTextRunStart(
  segments: { kind: string; part?: MessagePart }[],
  /** Requires prose (model text, without source) inside the block: a block of
   *  reasoning only — a turn that ended thinking, without writing again — does not count
   *  as final answer. Without this, the last prose of the message would become
   *  "narration" and the summary would have no answer to show. */
  requireProse = false,
): number {
  let runStart = -1
  let lastRunStart = -1
  let runHasProse = false
  for (let i = 0; i < segments.length; i++) {
    const part = segments[i].part
    // Engine text (nudge/todo/internal) is INVISIBLE to the run: its source
    // already erases it in the UI, so it neither starts a new block nor breaks the
    // current one. If it counted, a nudge after a tool would become the last
    // block and would erase the real answer (the "overlapping answer" symptom).
    if (segments[i].kind === 'part' && part?.type === 'text' && isEngineText(part.source)) {
      continue
    }
    const textish =
      segments[i].kind === 'part' &&
      part !== undefined &&
      (part.type === 'text' || part.type === 'reasoning')
    if (textish) {
      if (runStart === -1) {
        runStart = i
        runHasProse = false
      }
      if (part.type === 'text' && part.source === undefined) runHasProse = true
      if (!requireProse || runHasProse) lastRunStart = runStart
    } else {
      runStart = -1
      runHasProse = false
    }
  }
  return lastRunStart
}

/**
 * The ANSWER of a turn: the prose of the last contiguous text block.
 *
 * It is what the person reads as the final answer in the chat — and therefore also what
 * should show up in a preview (native banner, phone alert). The prose
 * before a tool is narration ("thinking out loud"), not an answer: in a
 * turn with tools, the FIRST text part is always the preamble.
 *
 * With no prose block (a turn of reasoning/tools only) it returns "".
 */
export function lastProseText(message: ChatMessage): string {
  const parts = message.parts
  const start = lastTextRunStart(
    parts.map((part) => ({ kind: 'part', part })),
    true,
  )
  const block = start === -1 ? parts : parts.slice(start)
  return block
    .filter((part): part is TextPart => part.type === 'text' && part.source === undefined)
    .map((part) => part.text)
    .join('\n')
    .trim()
}

/**
 * Text that the READ-ALOUD speaks: the final answer of the message, and only it.
 *
 * It is `lastProseText` without what is not readable: the orbit-ui JSON and the code of the
 * mermaid diagram are inline images, and speaking both would be reading chart
 * configuration out loud. User prose is never read (returns "").
 *
 * It lives in shared because BOTH ends speak: the desktop through the `ChunkPlayer` of
 * the renderer (streaming IPC) and the phone asking for the WAV in `/api/voice/speak`.
 * If each side had its own rule, the same turn would come out different on the
 * computer and on the phone.
 */
export function speakableText(message: ChatMessage): string {
  if (message.role !== 'assistant') return ''
  return lastProseText(message)
    .replace(/```(?:orbit-ui|mermaid)[\s\S]*?(?:```|$)/g, '')
    .trim()
}

